import{Z as e,e as a,f as t,a0 as i}from"./chunks/framework.DmpHOl9T.js";const f=JSON.parse('{"title":"Migrations & Upgrades","description":"","frontmatter":{},"headers":[],"relativePath":"guides/migrations-upgrades/index.md","filePath":"guides/migrations-upgrades/index.md","lastUpdated":1782532814000}'),o={name:"guides/migrations-upgrades/index.md"};function s(n,r,m,d,g,p){return a(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="migrations-upgrades" tabindex="-1">Migrations &amp; Upgrades <a class="header-anchor" href="#migrations-upgrades" aria-label="Permalink to &quot;Migrations &amp; Upgrades&quot;">​</a></h1><p>Upgrading between Formie versions and migrating from other form plugins.</p><h2 id="major-upgrade-—-real-project-checklist" tabindex="-1"><a href="/guides/migrations-upgrades/major-upgrade-real-project-checklist">Major Upgrade — Real-Project Checklist</a> <a class="header-anchor" href="#major-upgrade-—-real-project-checklist" aria-label="Permalink to &quot;[Major Upgrade — Real-Project Checklist](/guides/migrations-upgrades/major-upgrade-real-project-checklist)&quot;">​</a></h2><p>Major Formie upgrades touch templates, custom fields, integrations, front-end JavaScript, spam settings, and status APIs. This checklist distils <a href="/get-started/upgrading-from-v3">Upgrading From v3</a> into a practical project runbook — for upgrading an older Formie codebase.</p><h2 id="migrating-from-freeform" tabindex="-1"><a href="/guides/migrations-upgrades/migrating-from-freeform">Migrating from Freeform</a> <a class="header-anchor" href="#migrating-from-freeform" aria-label="Permalink to &quot;[Migrating from Freeform](/guides/migrations-upgrades/migrating-from-freeform)&quot;">​</a></h2><p>If your Craft site runs <a href="https://docs.solspace.com/craft/freeform/v5/" target="_blank" rel="noreferrer">Solspace Freeform</a>, Formie&#39;s migration tool copies forms, email notifications, and submissions into Formie without modifying Freeform data. This guide walks through the migration UI, handle collisions, unsupported fields, and what to verify before switching production forms to Formie.</p><h2 id="migrating-from-sprout-forms" tabindex="-1"><a href="/guides/migrations-upgrades/migrating-from-sprout-forms">Migrating from Sprout Forms</a> <a class="header-anchor" href="#migrating-from-sprout-forms" aria-label="Permalink to &quot;[Migrating from Sprout Forms](/guides/migrations-upgrades/migrating-from-sprout-forms)&quot;">​</a></h2><p>If your Craft site uses <a href="https://sprout.barrelstrengthdesign.com/docs/forms/" target="_blank" rel="noreferrer">Sprout Forms</a>, Formie&#39;s migration tool copies forms, email notifications, and submissions into Formie without modifying Sprout data. Sprout Forms layouts are typically simpler than Freeform — migration is often straightforward with few unsupported field types.</p><h2 id="template-compatibility-audit-after-upgrade" tabindex="-1"><a href="/guides/migrations-upgrades/template-compatibility-audit-after-upgrade">Template Compatibility Audit After Upgrade</a> <a class="header-anchor" href="#template-compatibility-audit-after-upgrade" aria-label="Permalink to &quot;[Template Compatibility Audit After Upgrade](/guides/migrations-upgrades/template-compatibility-audit-after-upgrade)&quot;">​</a></h2><p>After a major upgrade, most regressions show up in Twig templates and front-end JavaScript — renamed render helpers, asset flags, submission value methods, and DOM event names. This audit is a systematic search-and-verify pass you can run on any project before production cutover.</p>',10)])])}const l=e(o,[["render",s]]);export{f as __pageData,l as default};
